const b=$input.first().json.body??{};
if(b.agentKey!=='ancfz'||typeof b.ticketId!=='string'||
   !/^[0-9a-f]{8}-[0-9a-f-]{27,31}$/i.test(b.ticketId)||
   typeof b.licenceNumber!=='string'||
   !/^ANCFZ-TEST-[A-Z0-9-]{4,40}$/.test(b.licenceNumber))
  throw Error('Invalid synthetic renewal lookup');
return [{json:{licenceNumber:b.licenceNumber}}];

const licenceNumber=$('Validate Licence Request').first().json.licenceNumber;
const all=$input.all().map(x=>x.json).filter(x=>x&&x.licenceNumber===licenceNumber);
let output={status:'not_found'};
if(all.length>1)output={status:'review'};
else if(all.length===1){
  const row=all[0];
  const clean=(value,n)=>typeof value==='string'?value.trim().slice(0,n):'';
  const companyName=clean(row.companyName,200);
  const licenceStatus=clean(row.licenceStatus,32).toLowerCase();
  const expiresOn=clean(row.expiresOn,20).slice(0,10);
  const offeringKey=clean(row.offeringKey,128);
  const termYears=Number(row.termYears);
  if(companyName&&['active','expired','suspended','cancelled'].includes(licenceStatus)&&
     /^\d{4}-\d{2}-\d{2}$/.test(expiresOn)&&
     /^renewal_[a-z0-9_]{1,110}$/.test(offeringKey)&&
     Number.isInteger(termYears)&&termYears>=1&&termYears<=5)
    output={status:'found',licenceNumber,companyName,licenceStatus,
      expiresOn,offeringKey,termYears};
  else output={status:'review'};
}
return [{json:output}];
